<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {api,post,download,stamp} from '../api'
const page=ref(1),rows=ref<any[]>([]),settings=ref<any>({factory:'聚星数据平台-制造MES',backupIntervalHours:'24',backupRetentionDays:'30'}),preview=ref<any>(),confirmation=ref(''),id=ref(''),busy=ref(false),status=ref<any>();let timer:ReturnType<typeof setInterval>
async function load(){try{rows.value=await api('/api/backups');status.value=await api('/api/maintenance')}catch{}}
async function create(){await post('/api/backups');await load()}
async function preflight(row:any){busy.value=true;try{id.value=row.id;preview.value=await post('/api/backups/'+row.id+'/preview');confirmation.value=''}catch(e:any){ElMessage.error(e.message)}finally{busy.value=false}}
async function restore(){try{await post('/api/backups/'+id.value+'/restore',{ticket:preview.value.ticket,confirmation:confirmation.value});preview.value=null;ElMessage.warning('开始维护恢复，完成后会退出全部会话，请重新登录');await load()}catch(e:any){ElMessage.error(e.message)}}
async function save(){try{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(settings.value)});ElMessage.success('配置已保存')}catch(e:any){ElMessage.error(e.message)}}
onMounted(async()=>{await load();for(const s of await api('/api/admin/settings'))settings.value[s.key]=s.value;timer=setInterval(load,4000)});onUnmounted(()=>clearInterval(timer))

const statuses:Record<string,string>={Pending:'等待执行',Running:'执行中',Completed:'已完成',Failed:'失败',Idle:'正常运行',RecoveryRequired:'等待恢复处理'}
const visible=computed(()=>rows.value.slice((page.value-1)*8,page.value*8))
</script>
<template>
 <div class="settings-layout">
  <section class="panel"><div class="settings-section-title"><span>⌘</span><div><h2>基础信息</h2><p class="sub">工厂名称与系统标识</p></div></div><el-form label-position="top"><el-form-item label="工厂名称"><el-input v-model="settings.factory" placeholder="输入工厂名称"/></el-form-item></el-form><div class="settings-note">名称用于业务配置。软件名称统一为“聚星数据平台-制造MES”。</div><el-button type="primary" @click="save">保存配置</el-button></section>
  <section class="panel"><div class="settings-section-title"><span>◷</span><div><h2>自动备份策略</h2><p class="sub">数据库、SOP 与附件统一保护</p></div></div><el-form label-position="top" class="admin-form"><el-form-item label="备份间隔（小时）"><el-input v-model="settings.backupIntervalHours" type="number" min="1"><template #append>小时</template></el-input></el-form-item><el-form-item label="保留时间（天）"><el-input v-model="settings.backupRetentionDays" type="number" min="1"><template #append>天</template></el-input></el-form-item></el-form><div class="settings-note">备份包含数据库、SOP、附件及非密钥配置。下载后请保存至独立介质。</div><el-button type="primary" @click="save">保存备份策略</el-button></section>
 </div>
 <div class="settings-actions"><span><i class="dot"></i>维护状态：{{statuses[status?.status]||status?.status||'正在获取'}}</span><el-button type="primary" @click="create">＋ 立即备份数据库与附件</el-button></div>
 <section class="panel admin-list"><div class="list-title"><div><h2>备份记录 <span class="count-pill">{{rows.length}}</span></h2><p class="sub">查看执行结果、下载备份或发起恢复前校验</p></div></div><el-alert v-if="status&&status.status!=='Idle'" :title="'维护状态：'+(statuses[status.status]||status.status)" :description="status.error" :closable="false"/><el-table :data="visible" empty-text="尚无备份记录，可创建首次备份"><el-table-column label="备份时间" min-width="200"><template #default="{row}">{{stamp(row.at)}}</template></el-table-column><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="row.status==='Completed'?'success':row.status==='Failed'?'danger':'warning'" round>{{statuses[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column prop="error" label="执行说明" min-width="200" show-overflow-tooltip><template #default="{row}">{{row.error||'—'}}</template></el-table-column><el-table-column label="操作" width="240"><template #default="{row}"><el-button link :disabled="row.status!=='Completed'" type="primary" @click="download('/api/backups/'+row.id+'/download','mes-backup-'+row.id+'.zip')">下载备份</el-button><el-button link :disabled="row.status!=='Completed'||busy" type="danger" @click="preflight(row)">恢复前校验</el-button></template></el-table-column></el-table><div class="list-pagination"><span>共 {{rows.length}} 条备份</span><el-pagination v-model:current-page="page" :page-size="8" :total="rows.length" layout="prev, pager, next" background/></div></section>
 <el-dialog :model-value="!!preview" title="管理员确认恢复范围" width="760" @close="preview=null"><template v-if="preview"><el-alert :title="preview.scope" type="warning" :closable="false"/><p>备份时间：{{stamp(preview.manifest.createdAt)}}；附件数：{{Object.keys(preview.manifest.files).length}}</p><p>数据库与文件摘要校验通过。恢复将替换当前业务状态，先自动备份当前状态。请输入：</p><code>{{preview.confirmation}}</code><el-input v-model="confirmation" placeholder="输入上方完整确认文字"/><el-button type="danger" :disabled="confirmation!==preview.confirmation" @click="restore">确认并开始恢复</el-button></template></el-dialog>
</template>
